// n8n Code node (JS)
// Objetivo: devolver { primerDia, ultimoSabado } (YYYY-MM-DD)
// - ultimoSabado: último sábado <= hoy (en zona America/Montevideo)
// - primerDia: normalmente el 1ro del mes de "ultimoSabado"
//   PERO si estamos en el PRIMER sábado del mes y quedaron días "perdidos"
//   del mes anterior (desde el día posterior al último sábado del mes anterior
//   hasta el último día del mes anterior), entonces primerDia = (último sábado del mes anterior + 1 día).

function toTZDate(tz) {
  // Crea un Date "local" consistente para esa TZ usando toLocaleString
  const now = new Date();
  return new Date(now.toLocaleString('en-US', { timeZone: tz }));
}

function atStartOfDay(d) {
  const x = new Date(d);
  x.setHours(0, 0, 0, 0);
  return x;
}

function addDays(d, n) {
  const x = new Date(d);
  x.setDate(x.getDate() + n);
  return x;
}

function isoYYYYMMDD(d) {
  const y = d.getFullYear();
  const m = String(d.getMonth() + 1).padStart(2, '0');
  const day = String(d.getDate()).padStart(2, '0');
  return `${y}-${m}-${day}`;
}

// 1) Fecha "ahora" en Montevideo
const tz = 'America/Montevideo';
const uyNow = atStartOfDay(toTZDate(tz));

// 2) Calcular último sábado (<= hoy) en esa TZ
// JS: getDay() => 0=domingo ... 6=sábado
const dayOfWeek = uyNow.getDay();
const offsetToLastSaturday = (dayOfWeek + 1) % 7; // sábado => 0, domingo => 1, lunes => 2, ...
const lastSaturday = addDays(uyNow, -offsetToLastSaturday);

// 3) Determinar si lastSaturday es el PRIMER sábado del mes
const year = lastSaturday.getFullYear();
const month = lastSaturday.getMonth();
const firstOfMonth = new Date(year, month, 1);
firstOfMonth.setHours(0, 0, 0, 0);

// Primer sábado del mes: desde el día 1 avanzar hasta sábado
const firstOfMonthDOW = firstOfMonth.getDay();
const offsetToFirstSaturday = (6 - firstOfMonthDOW + 7) % 7; // sábado=6
const firstSaturdayOfMonth = addDays(firstOfMonth, offsetToFirstSaturday);

let primerDiaDate = firstOfMonth;

// 4) Si estamos en el primer sábado del mes, revisar "días perdidos" del mes anterior
// Lógica:
// - Hallar el último día del mes anterior
// - Hallar el último sábado del mes anterior (<= último día)
// - Si el último sábado NO fue el último día, entonces hay días perdidos:
//     (último sábado + 1) ... (último día)
// - En ese caso, primerDia = último sábado del mes anterior + 1
if (lastSaturday.getTime() === firstSaturdayOfMonth.getTime()) {
  const lastDayPrevMonth = new Date(year, month, 0); // día 0 del mes actual => último del mes anterior
  lastDayPrevMonth.setHours(0, 0, 0, 0);

  const prevDOW = lastDayPrevMonth.getDay();
  const offsetPrevToLastSaturday = (prevDOW + 1) % 7;
  const lastSaturdayPrevMonth = addDays(lastDayPrevMonth, -offsetPrevToLastSaturday);

  // ¿Último sábado del mes anterior coincide con el último día? (si coincide, no hay "perdidos")
  if (lastSaturdayPrevMonth.getTime() !== lastDayPrevMonth.getTime()) {
    // Incluir los días posteriores al último sábado del mes anterior
    primerDiaDate = addDays(lastSaturdayPrevMonth, 1);
  }
}

// 5) Output final
return [
  {
    json: {
      primerDia: isoYYYYMMDD(primerDiaDate),
      ultimoSabado: isoYYYYMMDD(lastSaturday),
    },
  },
];

